needed_n <- function(rdist, threshold = 0.05) {
  for (n in c(5, 10, 20, 30, 50, 100)) {
    m <- simulate_means(rdist, n, k = 1000)
    if (shapiro.test(m)$p.value > threshold) return(n)
  }
  NA
}

