# As an infix operator (works, but has a design smell):
`%titlecase%` <- function(x, unused) {
  paste0(toupper(substr(x, 1, 1)), substr(x, 2, nchar(x)))
}
"hello" %titlecase% NULL
#> [1] "Hello"

