my_detect_outliers <- function(x, method = "iqr") {
  if (method == "iqr") {
    q1 <- quantile(x, 0.25)
    q3 <- quantile(x, 0.75)
    iqr <- q3 - q1
    x[x < q1 - 1.5 * iqr | x > q3 + 1.5 * iqr]
  } else if (method == "zscore") {
    z <- (x - mean(x)) / sd(x)
    x[abs(z) > 3]
  } else {
    stop("method must be 'iqr' or 'zscore'")
  }
}

