set.seed(2402)
mp14_play <- function(strategy = c("stay", "switch")) {
  strategy <- match.arg(strategy)
  car      <- sample(1:3, 1)
  pick     <- sample(1:3, 1)
  doors    <- setdiff(1:3, c(car, pick))
  host_opens <- if (length(doors) == 1) doors else sample(doors, 1)
  if (strategy == "stay") {
    final <- pick
  } else {
    final <- setdiff(1:3, c(pick, host_opens))
  }
  final == car
}

