# Simple curry helper for any function
my_curry <- function(fn) {
  params <- formals(fn)
  if (length(params) <= 1) return(fn)

  function(x) {
    remaining <- params[-1]
    new_fn <- function(...) do.call(fn, c(list(x), list(...)))
    if (length(remaining) <= 1) return(new_fn)
    my_curry(new_fn)
  }
}

