chart_for <- function(x, nm) {
  if (!is.numeric(x))                 return("not numeric")
  if (length(unique(x)) < 2)          return("constant -> barplot")
  if (diff(range(x)) < 1e-6)          return("near-constant -> jitter")
  return("normal -> hist")
