run_safely <- function(expr) {
  tryCatch(
    expr,
    error = function(e) {
      msg <- conditionMessage(e)
      match <- regmatches(msg, regexpr("object '([^']+)' not found", msg))
      if (length(match) > 0) {
        sub("object '([^']+)' not found", "\\1", match)
      } else {
        stop(e)
      }
    }
  )
}

