compare_stan_interfaces <- function(model_code) {
  time_rstan <- NA_real_
  ok_rstan <- FALSE
  time_cmdstan <- NA_real_
  ok_cmdstan <- FALSE

  if (requireNamespace("rstan", quietly = TRUE)) {
    t <- tryCatch(system.time(rstan::stan_model(model_code = model_code))[["elapsed"]],
                  error = function(e) NA_real_)
    time_rstan <- t
    ok_rstan <- !is.na(t)
  }

  if (requireNamespace("cmdstanr", quietly = TRUE)) {
    t <- tryCatch({
      f <- cmdstanr::write_stan_file(model_code)
      system.time(cmdstanr::cmdstan_model(f))[["elapsed"]]
    }, error = function(e) NA_real_)
    time_cmdstan <- t
    ok_cmdstan <- !is.na(t)
  }

  data.frame(
    interface = c("rstan", "cmdstanr"),
    success = c(ok_rstan, ok_cmdstan),
    compile_seconds = c(time_rstan, time_cmdstan)
  )
}

my_comparison <- compare_stan_interfaces("parameters { real y; } model { y ~ normal(0,1); }")
print(my_comparison)
#>   interface success compile_seconds
#> 1     rstan   FALSE              NA
#> 2  cmdstanr   FALSE              NA

diagnose_subscript <- function(x, i) {
  if (is.null(dim(x))) {
    n <- length(x)
    cat("Type: ", class(x), " | length: ", n, " | index: ", i, "\n", sep = "")
    if (i > n) cat("Over by ", i - n, " element(s).\n", sep = "")
  } else {
    d <- dim(x)
    cat("Type: ", class(x)[1], " | dim: ", d[1], "x", d[2],
        " | index: [", i[1], ",", i[2], "]\n", sep = "")
    if (i[1] > d[1]) cat("Row over by ", i[1] - d[1], ".\n", sep = "")
    if (i[2] > d[2]) cat("Col over by ", i[2] - d[2], ".\n", sep = "")
  }
}

