make_fib_memo <- function() {
  cache <- new.env(parent = emptyenv())

  fib_inner <- function(n) {
    key <- as.character(n)
    if (exists(key, envir = cache)) {
      return(get(key, envir = cache))
    }
    val <- if (n <= 1) n else fib_inner(n - 1) + fib_inner(n - 2)
    assign(key, val, envir = cache)
    val
  }

  fib_inner
}

