# Loop version — same result, slower, more code
normalise_loop <- function(x) {
  out <- numeric(length(x))
  lo <- min(x); hi <- max(x)
  for (i in seq_along(x)) {
    out[i] <- (x[i] - lo) / (hi - lo)
  }
  out
}

