once <- function(fn) {
  force(fn)
  cache <- new.env(parent = emptyenv())
  cache$done <- FALSE

  function() {
    if (!cache$done) {
      cache$value <- fn()
      cache$done  <- TRUE
    }
    cache$value
  }
}

