na_report <- function(df) {
  missing_count <- sapply(df, function(col) {
    if (is.numeric(col)) sum(!is.finite(col))
    else sum(is.na(col))
  })
  data.frame(
    column = names(missing_count),
    missing = unname(missing_count),
    row.names = NULL
  )
}

