pick_language <- function(goal, background = "unknown") {
  goal <- tolower(goal)
  background <- tolower(background)

  if (grepl("stat|research|biostat|pharma|academ|clinical", goal)) return("R")
  if (grepl("deep|ml engineer|production|nlp|llm|cv", goal))       return("Python")
  if (grepl("web|backend|api|devops", goal))                       return("Python")
  if (grepl("analysis|dashboard|report|visual", goal)) {
    return(ifelse(background == "stats", "R", "Either"))
  }
  "Either"
}

sapply(
  c("biostatistics",
    "deep learning for images",
    "dashboard and reports",
    "web backend"),
  pick_language
)
#>          biostatistics deep learning for images     dashboard and reports
#>                    "R"                 "Python"                 "Either"
#>            web backend
#>               "Python"

stata_to_r <- function(cmd) {
  if (grepl("^regress ", cmd)) {
    parts <- strsplit(sub("^regress ", "", cmd), " ")[[1]]
    sprintf("lm(%s ~ %s, data = df)", parts[1], paste(parts[-1], collapse = " + "))
  } else if (grepl("^gen ", cmd)) {
    sub("^gen ", "df <- df |> mutate(", paste0(cmd, ")"))
  } else if (grepl("^keep if ", cmd)) {
    sub("^keep if ", "df <- df |> filter(", paste0(cmd, ")"))
  } else {
    "unknown"
  }
}

stata_to_r("regress y x1 x2")
#> [1] "lm(y ~ x1 + x2, data = df)"
stata_to_r("gen z = x + 1")
#> [1] "df <- df |> mutate(z = x + 1)"
stata_to_r("keep if x > 0")
#> [1] "df <- df |> filter(x > 0)"

