#> [1] 3628800

factorial_tramp(5000)
#> [1] Inf

# Mutual recursion with trampolines
trampoline2 <- function(f, ...) {
  function(...) {
    ret <- f(...)
    while (is.function(ret)) ret <- ret()
    ret
  }
}

