my_flatten <- function(lst) {
  result <- c()
  stack <- list(lst)
  while (length(stack) > 0) {
    current <- stack[[1]]
    stack <- stack[-1]
    if (is.list(current)) {
      stack <- c(rev(current), stack)
    } else {
      result <- c(result, current)
    }
  }
  result
}

