my_bsearch <- function(vec, target, low = 1, high = length(vec)) {
  if (low > high) return(NA)
  mid <- (low + high) %/% 2
  if (vec[mid] == target) return(mid)
  if (vec[mid] < target) {
    Tailcall(my_bsearch, vec, target, mid + 1, high)
  } else {
    Tailcall(my_bsearch, vec, target, low, mid - 1)
  }
}

